def parse_headers(s):
    out = {}
    i, n = 0, len(s)
    while i < n:
        j = s.find(':', i)
        if j < 0:
            break
        key = s[i:j].strip()
        k = j + 1
        while k < n and s[k] == ' ':
            k += 1
        quoted = k < n and s[k] == '"'
        if quoted:
            e = s.find('"', k + 1)
            if e < 0:
                val, i = s[k + 1:], n
            else:
                val = s[k + 1:e]
                i = e + 1
                while i < n and s[i] != ';':
                    i += 1
                i += 1
        else:
            e = s.find(';', k)
            if e < 0:
                val, i = s[k:], n
            else:
                val, i = s[k:e], e + 1
        if key:
            out[key] = val if quoted else val.strip()
    return out

